//! NBT serialization with sorted compound keys.
//!
//! `NbtCompound` keeps its tags in a `HashMap`, so its own serializers write the keys in a random
//! order. Generated byte literals built from them changed on every codegen run.

use pumpkin_nbt::{
    COMPOUND_ID, END_ID, Nbt,
    compound::NbtCompound,
    serializer::{NbtWriteHelper, NbtWriteHelperBedrock, NbtWriteHelperJava},
    tag::NbtTag,
};

fn write_compound_content<W: NbtWriteHelper>(compound: NbtCompound, w: &mut W) {
    let mut tags: Vec<_> = compound.child_tags.into_iter().collect();
    tags.sort_by(|(a, _), (b, _)| a.cmp(b));
    for (name, tag) in tags {
        w.write_u8(tag.get_type_id()).expect("write to a Vec");
        w.write_string(&name).expect("write to a Vec");
        write_tag_data(tag, w);
    }
    w.write_u8(END_ID).expect("write to a Vec");
}

fn write_tag_data<W: NbtWriteHelper>(tag: NbtTag, w: &mut W) {
    match tag {
        NbtTag::Compound(compound) => write_compound_content(compound, w),
        NbtTag::List(list) => {
            // Same element type rule as `NbtTag::serialize_data`: a mixed list is written as a
            // list of compounds, each tag that is not already a compound wrapped under "".
            let mut element_id = END_ID;
            for tag in &list {
                let id = tag.get_type_id();
                if element_id == END_ID {
                    element_id = id;
                } else if element_id != id {
                    element_id = COMPOUND_ID;
                    break;
                }
            }
            w.write_u8(element_id).expect("write to a Vec");
            w.write_i32(list.len() as i32).expect("write to a Vec");
            for tag in list {
                if element_id == COMPOUND_ID && !matches!(tag, NbtTag::Compound(_)) {
                    let mut wrapper = NbtCompound::new();
                    wrapper.put("", tag);
                    write_compound_content(wrapper, w);
                } else {
                    write_tag_data(tag, w);
                }
            }
        }
        other => other.serialize_data(w).expect("write to a Vec"),
    }
}

/// Same bytes as `NbtTag::serialize` on the Java writer, with the keys of every compound sorted.
/// For a compound this equals `Nbt::write_unnamed`.
pub fn write_tag(tag: NbtTag) -> Vec<u8> {
    let mut bytes = Vec::new();
    let mut writer = NbtWriteHelperJava::new(&mut bytes);
    writer.write_u8(tag.get_type_id()).expect("write to a Vec");
    write_tag_data(tag, &mut writer);
    bytes
}

/// Same bytes as `Nbt::write_bedrock`, with the keys of every compound sorted.
pub fn write_bedrock(nbt: Nbt) -> Vec<u8> {
    let mut bytes = Vec::new();
    let mut writer = NbtWriteHelperBedrock::new(&mut bytes);
    writer.write_u8(COMPOUND_ID).expect("write to a Vec");
    NbtTag::String(nbt.name.into())
        .serialize_data(&mut writer)
        .expect("write to a Vec");
    write_compound_content(nbt.root_tag, &mut writer);
    bytes
}
